nav.example:
# 列出当前所有环境变量
set
# 为一个环境变量设置指定的值
set {{变量名}}={{值}}
# 列出以指定字符串开头的环境变量
set {{变量名}}
# 提示用户输入指定变量的值
set /p {{变量名}}={{提示信息}}

file.example:
# 仅显示文件名
basename {{路径/到/文件}}
# 显示路径字符最右边表示目录的字符
basename {{路径/到/目录/}}
# 展示无后缀的文件名称
basename {{路径/到/文件}} {{后缀}}

# 将文件复制到另一个位置
cp {{路径/到/源_文件.ext}} {{路径/到/目标文件.ext}}
# 将文件复制到另一个文件夹，并保留原来的文件名
cp {{路径/到/源文件.ext}} {{路径/到/目标的目录}}
# 以递归方式将文件夹内的内容复制到另一个位置（如果目标文件夹存在，则将此文件夹复制到目标文件夹中）
cp {{[-r|--recursive]}} {{路径/到/源目录}} {{路径/到/目标目录}}
# 以详细模式递归复制目录（在复制文件时显示文件信息）
cp {{[-vr|--verbose --recursive]}} {{路径/到/源目录}} {{路径/到/目标目录}}

# 每行列出一个文件
exa {{[-1|--oneline]}}
# 列出所有文件，包括隐藏文件
exa {{[-a|--all]}}
# 以长格式列出所有文件（包含权限、所有者、大小和修改日期）
exa {{[-l|--long]}} {{[-a|--all]}}
# 列出文件，最大的排在最上面
exa {{[-r|--reverse]}} {{[-s|--sort]}} {{size}}

# 每行列出一个文件
eza {{[-1|--oneline]}}
# 列出所有文件，包括隐藏文件
eza {{[-a|--all]}}
# 以长格式列出所有文件（包含权限、所有者、大小和修改日期）
eza {{[-al|--all --long]}}
# 列出文件，最大的排在最上面
eza {{[-r|--reverse]}} {{[-s|--sort]}} {{size}}

# 在当前目录中递归查找匹配特定模式的文件
fd "{{正则表达式}}"
# 在特定目录中查找文件
fd "{{正则表达式}}" {{路径/到/文件}}
# 查找具有特定扩展名的文件
fd {{[-e|--extension]}} {{扩展名}}
# 仅查找匹配特定模式的文件夹
fd "{{正则表达式}}" {{[-t|--type]}} {{[d|directory]}}

# 提供指定文件类型的描述，对于没有文件扩展名的文件可以正常工作
file {{文件名}}
# 查看压缩文件并确定其中的文件类型
file {{[-z|--uncompress]}} {{xxx.zip}}
# 允许文件与特殊文件或设备文件一起使用
file {{[-s|--special-files]}} {{文件名}}
# 不要在第一个文件类型匹配时停止；继续执行直到文件结束
file {{[-k|--keep-going]}} {{文件名}}

# 搜索单个目录
jdupes {{路径/到/目录}}
# 搜索多个目录
jdupes {{目录1 目录2 ...}}
# 递归地搜索所有目录
jdupes {{[-r|--recurse]}} {{路径/到/目录}}
# 递归地搜索目录，并让用户选择要保留的文件
jdupes {{[-d|--delete]}} {{[-r|--recurse]}} {{路径/到/目录}}

# 创建一个目录
mkdir {{目录名}}
# 递归创建目录及子目录
mkdir {{子目录名}}

# 创建指向文件的符号链接
mklink {{链接文件的路径}} {{源文件路径}}
# 创建指向目录的符号链接
mklink /d {{链接文件的路径}} {{源目录路径}}
# 创建指向文件的硬链接
mklink /h {{链接文件的路径}} {{源目录路径}}
# 创建目录链接
mklink /j {{链接文件的路径}} {{源目录路径}}

# 重命名文件或目录，当目标不是一个已存在的目录时
mv {{路径/到/源}} {{路径/到/目标}}
# 将文件或目录移动到已存在的目录中
mv {{路径/到/源}} {{路径/到/已存在的目录}}
# 将多个文件移动到已存在的目录中，并保持文件名不变
mv {{路径/到/源1 路径/到/源2 ...}} {{路径/到/已存在的目录}}
# 覆盖现有文件前无需确认
mv {{[-f|--force]}} {{路径/到/源}} {{路径/到/目标}}

# 删除指定文件
rm {{路径/到/文件1 路径/到/文件2 ...}}
# 删除指定文件，忽略不存在的文件
rm {{[-f|--force]}} {{路径/到/文件1 路径/到/文件2 ...}}
# 交互式地删除多个文件，每次删除前都会有提示
rm {{[-i|--interactive]}} {{路径/到/文件1 路径/到/文件2 ...}}
# 删除文件并打印删除信息
rm {{[-v|--verbose]}} {{路径/到/文件1 路径/到/文件2 ...}}

# 使用指定路径启动 `spf`
spf {{path/to/directory}}
# 使用多个路径启动 `spf`
spf {{path/to/directory1 path/to/directory2 ...}}
# 修复快捷键设置，补全缺失的按键
spf {{[--fh|--fix-hotkeys]}}
# 修复配置文件，补全缺失的项
spf {{[--fch|--fix-config-file]}}

# 创建指定的文件
touch {{路径/到/文件1 路径/到/文件2 ...}}
# 将文件的访问(a)或修改时间(m)设置为当前时间，如果文件不存在则不创建(-c)
touch {{[-c|--no-create]}} -{{a|m}} {{路径/到/文件1 路径/到/文件2 ...}}
# 将文件时间(-t)设置为指定值，如果文件不存在则不创建(-c)
touch {{[-c|--no-create]}} -t {{YYYYMMDDHHMM.SS}} {{路径/到/文件1 路径/到/文件2 ...}}
# 将文件时间设置为另一文件(-r,即文件 3)的时间，如果文件不存在则不创建(-c)
touch {{[-c|--no-create]}} {{[-r|--reference]}} {{路径/到/文件3}} {{路径/到/文件1 路径/到/文件2 ...}}

view.example:
# 寻找内容包含"小明"的文件，并列出所在的行数
ag {{小明}}
# 在指定目录中寻找内容包含 "foo" 的文件
ag {{小明}} {{指定的目录}}
# 寻找内容包含 "foo" 的文件，但只列出文件名
ag -l {{小明}}
# 忽略大小写，寻找内容包含 "ABC" 的文件，并只输出匹配的内容，而非整行
ag -i -o {{ABC}}

# 编码一个文件
base32 {{路径/到/文件}}
# 按特定宽度包装编码输出（“0”表示禁用包装）
base32 {{[-w|--wrap]}} {{0|76|...}} {{路径/到/文件}}
# 解码一个文件
base32 {{[-d|--decode]}} {{路径/到/文件}}
# 从标准输入编码
{{某指令}} | base32

# 编码一个文件
base64 {{路径/到/文件}}
# 按特定宽度包装编码输出（“0”表示禁用包装）
base64 {{[-w|--wrap]}} {{0|76|...}} {{路径/到/文件}}
# 解码一个文件
base64 {{[-d|--decode]}} {{路径/到/文件}}
# 从标准输入编码
{{某指令}} | base64

# 使用美化样式打印一个或多个文件的内容到 `stdout`
bat {{路径/到/文件1 路径/到/文件2 ...}}
# 将多个文件连接成一个目标文件
bat {{路径/到/文件1 路径/到/文件2 ...}} >{{路径/到/目标文件}}
# 移除修饰并禁用分页
bat {{[-pp|--style plain --pager never]}} {{路径/到/文件}}
# 使用不同的背景颜色高亮显示特定行或一行范围
bat {{[-H|--highlight-line]}} {{10|5:10|:10|10:|10:+5}} {{路径/到/文件}}

# 比较文件或目录
delta {{路径/到/旧文件或目录}} {{路径/到/新文件或目录}}
# 比较文件或目录，显示行号
delta {{[-n|--line-numbers]}} {{路径/到/旧文件或目录}} {{路径/到/新文件或目录}}
# 比较文件或目录，并排显示差异
delta {{[-s|--side-by-side]}} {{路径/到/旧文件或目录}} {{路径/到/新文件或目录}}
# 比较文件或目录，忽略任何 Git 配置设置
delta --no-gitconfig {{路径/到/旧文件或目录}} {{路径/到/新文件或目录}}

# 比较文件 （列出从`原文件`到`新文件`的修改）
diff {{原文件}} {{新文件}}
# 比较文件，忽视空白字符
diff {{[-w|--ignore-all-space]}} {{原文件}} {{新文件}}
# 比较文件，并排展示文件差异
diff {{[-y|--side-by-side]}} {{原文件}} {{新文件}}
# 比较文件，以统一形式展示不同区别 （ 形式同 `git diff`）
diff {{[-u|--unified]}} {{源文件}} {{新文件}}

# 运行 glow 并选择文件查看
glow
# 渲染 Markdown 文件到终端
glow {{路径/到/文件}}
# 使用分页器查看 Markdown 文件
glow {{[-p|--pager]}} {{路径/到/文件}}
# 从 URL 查看文件
glow {{https://example.com/file.md}}

# 通过管道将命令输出转换为 JSON
{{ifconfig}} | jc {{--ifconfig}}
# 通过魔术语法将命令输出转换为 JSON
jc {{ifconfig}}
# 通过管道输出格式化的 JSON
{{ifconfig}} | jc {{--ifconfig}} {{[-p|--pretty]}}
# 通过魔术语法输出格式化的 JSON
jc {{[-p|--pretty]}} {{ifconfig}}

# 根据第一个（默认）字段合并两个文件
join {{路径/到/文件1}} {{路径/到/文件2}}
# 使用逗号（而不是空格）作为字段分隔符合并两个文件
join -t ',' {{路径/到/文件1}} {{路径/到/文件2}}
# 将文件 1 的字段 3 与文件 2 的字段 1 合并
join -1 {{3}} -2 {{1}} {{路径/到/文件1}} {{路径/到/文件2}}
# 为文件 1 中的每行未配对的行生成一行
join -a {{1}} {{路径/到/文件1}} {{路径/到/文件2}}

# 将 JSON5 `标准输入` 转换为 JSON 并输出到 `标准输出`
echo {{输入}} | json5
# 将 JSON5 文件转换为 JSON 并输出到 `标准输出`
json5 {{路径/到/输入文件.json5}}
# 将 JSON5 文件转换为指定的 JSON 文件
json5 {{路径/到/输入文件.json5}} {{[-o|--out-file]}} {{路径/到/输出文件.json}}
# 验证一个 JSON5 文件
json5 {{路径/到/输入文件.json5}} {{[-v|--validate]}}

# 将所有行合并为一行，使用 tab 作为分隔符
paste {{[-s|--serial]}} {{路径/到/文件}}
# 使用指定的分隔符将所有行合并为一行
paste {{[-s|--serial]}} {{[-d|--delimiters]}} {{分隔符}} {{路径/到/文件}}
# 并排合并两个文件，每个文件以 tab 分隔为单独的列
paste {{路径/到/文件1}} {{路径/到/文件2}}
# 并排合并两个文件，每个文件以指定的分隔符分隔为单独的列
paste {{[-d|--delimiters]}} {{分隔符}} {{路径/到/文件1}} {{路径/到/文件2}}

# 在 PDF 中查找与关键词匹配的行
pdfgrep {{关键词}} {{文件.pdf}}
# 包含每个匹配行的文件名和页码
pdfgrep {{[-H|--with-filename]}} {{[-n|--page-number]}} {{关键词}} {{文件.pdf}}
# 对以 "foo" 开头关键词搜索，返回前 3 个匹配项，不区分大小写
pdfgrep {{[-m|--max-count]}} 3 {{[-i|--ignore-case]}} '{{^foo}}' {{文件.pdf}}
# 在当前目录中扩展名为.pdf 的文件中递归查找关键词
pdfgrep {{[-r|--recursive]}} {{关键词}}

# 将文本文件打印到默认的打印机
print {{文件的路径}}
# 将文本文件打印到指定的打印机
print /d:{{打印机}} {{文件的路径}}

# 在当前目录中递归搜索匹配模式的内容（`regex`）
rg {{模式}}
# 在指定文件或目录中递归搜索匹配模式的内容
rg {{模式}} {{路径/到/文件或目录}}
# 搜索字面字符串模式
rg {{[-F|--fixed-strings]}} -- {{字符串}}
# 包含隐藏文件以及 `.gitignore` 中列出的条目
rg {{[-.|--hidden]}} --no-ignore {{模式}}

# 以升序对文件进行排序
sort {{路径/到/文件}}
# 以降序对文件进行排序
sort {{[-r|--reverse]}} {{路径/到/文件}}
# 以不区分大小写的方式对文件进行排序
sort {{[-f|--ignore-case]}} {{路径/到/文件}}
# 用数字而不是字母顺序对文件进行排序
sort {{[-n|--numeric-sort]}} {{路径/到/文件}}

# 仅显示每行一次
sort {{路径/到/文件}} | uniq
# 仅显示唯一的行
sort {{路径/到/文件}} | uniq {{[-u|--unique]}}
# 仅显示重复的行
sort {{路径/到/文件}} | uniq {{[-d|--repeated]}}
# 显示每行的出现次数及其内容
sort {{路径/到/文件}} | uniq {{[-c|--count]}}

# 计数文件中的行数
wc {{[-l|--lines]}} {{路径/到/文件}}
# 计数文件中的单词数
wc {{[-w|--words]}} {{路径/到/文件}}
# 计数文件中的字节数
wc {{[-c|--bytes]}} {{路径/到/文件}}
# 计数文件中的字符数（考虑所有多字节的字符）
wc {{[-m|--chars]}} {{路径/到/文件}}

# 显示匹配的文件的位置
where {{文件模式}}
# 显示匹配的文件的位置、大小和日期
where /T {{文件模式}}
# 在指定的路径下递归搜索要匹配的文件
where /R {{目录的路径}} {{文件模式}}
# 只返回退出代码，不显示匹配文件列表
where /Q {{文件模式}}

# 以漂亮打印格式输出 YAML 文件（v4+）
yq eval {{路径/到/file.yaml}}
# 以漂亮打印格式输出 YAML 文件（v3）
yq read {{路径/到/file.yaml}} {{[-C|--colors]}}
# 输出仅包含数组的 YAML 文件中的第一个元素（v4+）
yq eval '.[0]' {{路径/到/file.yaml}}
# 输出仅包含数组的 YAML 文件中的第一个元素（v3）
yq read {{路径/到/file.yaml}} '[0]'

# 创建一个新的触发器、创建、搜索或资源
zapier scaffold {{trigger|search|create|resource}} {{名称}}
# 为生成的文件指定一个自定义目标目录
zapier scaffold {{trigger|search|create|resource}} {{名称}} {{[-d|--dest]}}={{路径/到/目录}}
# 在生成文件时覆盖已有文件
zapier scaffold {{trigger|search|create|resource}} {{名称}} {{[-f|--force]}}
# 从生成的文件中排除注释
zapier scaffold {{trigger|search|create|resource}} {{名称}} --no-help

perm.example:
# 取得指定文件的所有权
takeown /f {{路径/文件}}
# 取得指定目录的所有权
takeown /d {{路径/目录}}
# 取得指定目录和所有子目录的所有权
takeown /r /d {{路径/目录}}
# 将所有权更改为管理员组，而不是当前用户
takeown /a /f {{路径/文件}}

proc.example:
# 在终端中运行
glances
# 以网页服务器模式运行，在浏览器中查看结果
glances {{[-w|--webserver]}}
# 以服务器模式启动，允许其他 glances 客户端连接以查看数据
glances {{[-s|--server]}}
# 作为客户端连接到 glances 服务器
glances {{[-c|--client]}} {{主机名}}

# 显示本机的主机名
hostname
# 显示主机名的网络地址
hostname {{[-i|--ip-address]}}
# 显示 FQDN（完全限定域名）
hostname {{[-f|--fqdn]}}
# 设置本机主机名
hostname {{新主机名}}

# 打印 Java 进程的共享对象映射（类似 pmap 的输出）
jmap {{Java 进程号}}
# 打印堆摘要信息
jmap -heap {{文件名.jar}} {{Java 进程号}}
# 按类型打印堆使用的直方图
jmap -histo {{Java 进程号}}
# 将堆的内容转储到二进制文件中以使用 jhat 进行分析
jmap -dump:format=b,file={{路径/到/文件}} {{Java 进程号}}

# 从 JSON 或 JSON Lines 输入中打印表格
cat {{文件.json}} | jtbl
# 打印表格并指定用于换行的列宽
cat {{文件.json}} | jtbl --cols={{宽度}}
# 打印表格并截断行而不是换行
cat {{文件.json}} | jtbl {{[-t|--truncate]}}
# 打印表格并不换行或截断行
cat {{文件.json}} | jtbl {{[-n|--no-wrap]}}

# 显示系统信息
neofetch
# 在输出中显示或隐藏指定的信息行，'信息名称'是配置文件中的函数名称，例如 memory
neofetch --{{enable|disable}} {{信息名称}}
# 隐藏或显示操作系统架构信息
neofetch --os_arch {{on|off}}
# 启用或禁用输出中的 CPU 品牌信息
neofetch --cpu_brand {{on|off}}

# 按秒数延迟
sleep {{seconds}}
# 在 20 秒延迟后执行指定命令
sleep 20 && {{command}}

# 显示当前正在运行的进程
tasklist
# 使用指定的格式显示当前进程列表
tasklist /fo {{table|list|csv}}
# 已匹配的方式（`.exe`, `.dll`）显示当前运行的进程
tasklist /m {{匹配模式}}
# 显示在远程计算机上运行的进程
tasklist /s {{远程主机名}} /u {{用户名}} /p {{密码}}

# 启动 Linux Shell（在默认发行版中）
wsl {{shell_命令}}
# 在不使用 Shell 的情况下运行 Linux 命令
wsl {{[-e|--exec]}} {{命令}} {{命令参数}}
# 指定特定的发行版
wsl {{[-d|--distribution]}} {{发行版}} {{shell_命令}}
# 列出所有可用发行版
wsl {{[-l|--list]}}

# 启动一个新的命名会话
zellij {{[-s|--session]}} {{名称}}
# 列出现有会话
zellij {{[ls|list-sessions]}}
# 附加到最近使用的会话
zellij {{[a|attach]}}
# 打开一个新窗格（在 zellij 会话中）
<Alt n>

net.example:
# 向目标 URL 执行 100 次 HTTP GET 请求
ab -n 100 {{url}}
# 使用 10 个并发请求，同时向目标 URL 执行 100 次 HTTP GET 请求
ab -n 100 -c 10 {{url}}
# 使用来自文件的 JSON 负载对 URL 执行 100 个 HTTP POST 请求
ab -n 100 -T {{application/json}} -p {{path/to/file.json}} {{url}}
# 使用 HTTP [K]eep Alive，即在一个 HTTP 会话中执行多个请求
ab -k {{url}}

# 运行 AdGuard Home
AdGuardHome
# 使用给定的配置文件运行 AdGuard Home
AdGuardHome --config {{给定的/配置文件.yaml}}
# 设置存储数据的工作目录
AdGuardHome --work-dir {{工作目录/路径}}
# 安装或卸载 AdGuard Home 的服务
AdGuardHome --service {{install|uninstall}}

# 运行并生成一个私钥和证书
agate --content {{路径/到/内容}}/ --addr {{[::]:1965}} --addr {{0.0.0.0:1965}} --hostname {{example.com}} --lang {{en-US}}
# 启动服务器
agate {{路径/到/目录}}
# 显示帮助
agate {{[-h|--help]}}

# 打开特定文件或目录
agy {{路径/到/文件或目录}}
# 比较两个文件
agy {{[-d|--diff]}} {{路径/到/文件1}} {{路径/到/文件2}}
# 传入提示词来运行一个在当前工作目录的聊天会话
agy chat "{{提示词}}"
# 安装或卸载特定扩展
agy --{{install|uninstall}}-extension {{发布者.扩展|路径/到/扩展.vsix}}

# 共享文件或目录
airshare {{code}} {{路径/到/文件或目录1 路径/到/文件或目录2 ...}}
# 接收文件
airshare {{code}}
# 主机接收服务器（使用此选项可以通过 Web 接口上传文件）
airshare --upload {{code}}
# 将文件或目录发送到接收服务器
airshare --upload {{code}} {{路径/到/文件或目录1 路径/到/文件或目录2 ...}}

# 显示当前的 ARP 表
arp -a
# 删除特定条目
arp -d {{地址}}
# 创建指定条目
arp -s {{地址}} {{MAC 地址}}

# 链接下载
axel {{超链接}}
# 链接下载，指定文件名
axel {{超链接}} {{[-o|--output]}} {{路径/到/文件}}
# 多连接数下载
axel {{[-n|--num-connections]}} {{连接数量}} {{超链接}}
# 查询镜像
axel {{[-S|--search=]}}{{镜像数量}} {{超链接}}

# 启动 `btop`
btop
# 使用指定预设启动 `btop`
btop {{[-p|--preset]}} {{0..9}}
# 使用 16 种颜色和 TTY 友好的图形符号在 TTY 模式下启动 `btop`
btop {{[-t|--tty]}}
# 在 256 色模式而不是 24 位颜色模式下启动 `btop`
btop {{[-l|--low-color]}}

# 发起 HTTP GET 请求，将响应内容输出到 `stdout`
curl {{https://example.com}}
# 发起 HTTP GET 请求，自动跟随所有 `3xx` 重定向，将响应头和内容输出到 `stdout`
curl {{[-L|--location]}} {{[-D|--dump-header]}} - {{https://example.com}}
# 按照 URL 指定的文件名保存下载内容
curl {{[-O|--remote-name]}} {{https://example.com/filename.zip}}
# 以表单编码格式发送数据（`application/x-www-form-urlencoded` 类型的 POST 请求）。如需从 `stdin` 读取数据，可使用 `--data @file_name` 或 `--data @'-'`
curl {{[-X|--request]}} POST {{[-d|--data]}} '{{name=bob}}' {{http://example.com/form}}

# 使用默认配置文件（当前目录下的 `frpc.ini`）启动服务
frpc
# 使用新的 TOML 配置文件启动服务
frpc {{[-c|--config]}} {{路径/到/frpc.toml}}
# 使用指定的配置文件启动服务
frpc {{[-c|--config]}} {{路径/到/文件}}
# 检查配置文件的有效性
frpc verify {{[-c|--config]}} {{路径/到/文件}}

# 使用默认配置文件启动服务（假定当前目录中存在 `frps.ini`）
frps
# 使用新的 TOML 配置文件启动服务
frps {{[-c|--config]}} {{路径/到/frps.toml}}
# 使用指定的配置文件启动服务
frps {{[-c|--config]}} {{路径/到/文件}}
# 检查配置文件的有效性
frps verify {{[-c|--config]}} {{路径/到/文件}}

# 交互式连接一个远程的 FTP 服务
ftp {{主机名}}
# 匿名登录
ftp -A {{主机名}}
# 初始连接时禁用自动登录
ftp -n {{主机名}}
# 运行包含 FTP 命令列表的文件
ftp -s:{{文件的路径}} {{主机名}}

# 列出所有端口
netstat {{[-a|--all]}}
# 列出所有被监听端口
netstat {{[-l|--listening]}}
# 列出监听的 TCP 端口
netstat {{[-t|--tcp]}}
# 显示 PID 和程序名
netstat {{[-p|--program]}}

# 使用不同的详细（[v]erbosity）级别扫描远程主机的前 1000 个端口
nmap -v{{1|2|3}} {{ip或主机名}}
# 对整个子网或单个主机进行非常激进的 ping 扫描
nmap -T5 -sn {{192.168.0.0/24|ip或主机名1,ip或主机名2,...}}
# 对来自文件的主机启用操作系统检测、版本检测、脚本扫描和路由跟踪
sudo nmap -A -iL {{路径/到/文件.txt}}
# 扫描特定的端口列表（使用 `-p-` 扫描从 1 到 65535 的所有端口）
nmap -p {{端口1,端口2,...}} {{ip或主机名1,ip或主机名2,...}}

# 使用系统默认名称服务器查询域名的 IP 地址（A 记录）
nslookup {{example.com}}
# 向指定名称服务器查询域名的 NS 记录
nslookup -type=NS {{example.com}} {{8.8.8.8}}
# 查询 IP 地址的反向解析（PTR 记录）
nslookup -type=PTR {{54.240.162.118}}
# 使用 TCP 协议查询任意（ANY）可用记录
nslookup -vc -type=ANY {{example.com}}

# Ping 并追踪主机的路由
pathping {{主机名}}
# 不要对主机名执行 IP 地址的反向查找
pathping {{主机名}} -n
# 指定要搜索目标的最大跃点数（默认值为 30）
pathping {{主机名}} -h {{最大跃点数}}
# 指定 ping 之间等待的毫秒数（默认值为 240）
pathping {{主机名}} -p {{时间}}

# Ping 主机
ping {{主机地址}}
# 仅 Ping 主机特定次数
ping -c {{次数}} {{主机地址}}
# Ping 主机，指定请求之间的间隔（以秒为单位）（默认为 1 秒）
ping -i {{间隔秒数}} {{主机地址}}
# Ping 主机而不尝试查找地址的符号名称
ping -n {{主机地址}}

# 启动交互式菜单来配置 rclone
rclone config
# 列出 rclone 远程目录的内容
rclone lsf {{远程名}}:{{路径/到/目录}}
# 将文件或目录从本地计算机复制到远程目标
rclone copy {{路径/到/本地文件或目录}} {{远程名}}:{{路径/到/目录}}
# 将过去 24 小时内修改过的文件从本地复制到远程，并向用户逐个文件确认
rclone copy {{[-i|--interactive]}} --max-age 24h {{远程名}}:{{路径/到/目录}} {{路径/到/本地目录}}

# 复制文件
rsync {{路径/到/来源}} {{路径/到/目标}}
# 使用归档模式递归拷贝文件，并保留所有属性，不解析软链接
rsync {{[-a|--archive]}} {{路径/到/来源}} {{路径/到/目标}}
# 将文件以归档模式并保留几乎所有属性进行传输，并以人类可读方式输出详细信息和进度条，中断时保留部分信息
rsync {{[-zvhP|--compress --verbose --human-readable --partial --progress]}} {{路径/到/来源}} {{路径/到/目标}}
# 以递归模式传输文件
rsync {{[-r|--recursive]}} {{路径/到/来源}} {{路径/到/目标}}

# 将本地文件复制到远程主机
scp {{路径/到/本地文件}} {{远程主机地址}}:{{路径/到/远程文件}}
# 连接到远程主机时使用特定端口
scp -P {{端口}} {{路径/到/本地文件}} {{远程主机地址}}:{{路径/到/远程文件}}
# 将文件从远程主机复制到本地目录
scp {{远程主机地址}}:{{路径/到/远程文件}} {{路径/到/本地目录}}
# 递归地将目录内容从远程主机复制到本地目录
scp -r {{远程主机地址}}:{{路径/到/远程目录}} {{路径/到/本地目录}}

# 连接到远程服务器
ssh {{用户名}}@{{远程主机地址}}
# 使用特定身份（私钥）连接到远程服务器
ssh -i {{路径/到/私钥文件}} {{用户名}}@{{远程主机地址}}
# 使用指定端口号连接到远程服务器
ssh {{用户名}}@{{远程主机地址}} -p {{端口号}}
# 在具有伪终端分配的远程服务器上运行命令，允许与远程命令进行交互
ssh {{用户名}}@{{远程主机地址}} -t {{命令}} {{命令参数}}

# 通过远程 SSH 服务器转发所有 IPv4 TCP 流量
sshuttle {{[-r|--remote]}} {{用户名}}@{{服务器名}} {{0.0.0.0/0}}
# 同时将所有 DNS 流量转发到服务器的默认 DNS 解析器
sshuttle --dns {{[-r|--remote]}} {{用户名}}@{{服务器名}} {{0.0.0.0/0}}
# 转发所有流量，除了发往特定子网的流量
sshuttle {{[-r|--remote]}} {{用户名}}@{{服务器名}} {{0.0.0.0/0}} {{[-x|--exclude]}} {{192.168.0.1/24}}
# 使用 tproxy 方法转发所有 IPv4 和 IPv6 流量
sshuttle --method tproxy {{[-r|--remote]}} {{用户名}}@{{服务器名}} {{0.0.0.0/0}} {{::/0}} {{[-x|--exclude]}} {{你本地 IP 地址}} {{[-x|--exclude]}} {{SSH 服务器的 IP 地址}}

# 同步两个目录（第一次同步这两个目录时会创建日志）
unison {{路径/到/目录1}} {{路径/到/目录2}}
# 自动接受（无冲突的）默认值
unison {{路径/到/目录1}} {{路径/到/目录2}} -auto
# 使用模式忽略某些文件
unison {{路径/到/目录1}} {{路径/到/目录2}} -ignore {{模式}}
# 查看文档
unison -doc {{主题}}

# 为当前目录启动 HTTP 服务器
updog
# 为指定目录启动 HTTP 服务器
updog --directory /{{路径/到/目录}}
# 在指定端口上启动 HTTP 服务器
updog --port {{端口}}
# 使用密码启动 HTTP 服务器（要登录，请将用户名留空，并在密码字段中输入密码）
updog --password {{密码}}

# 获取域名信息
whois {{example.com}}
# 获取 IP 地址信息
whois {{8.8.8.8}}
# 获取 IP 地址用于报告滥用的联系方式
whois -b {{8.8.8.8}}

# ping 指定的主机（省略则默认为 bing.com）
x ping {{host}}
# 以热力图形式显示 ping 结果
x ping {{[-m|--heatmap]}} {{host}}
# 以柱状图形式显示 ping 结果
x ping {{[-b|--bar]}} {{host}}
# 处理现有 ping 结果并以热力图显示
ping {{host}} | x ping vis {{[-m|--heatmap]}}

# 使用详细模式 Ping 主机的 80 端口（默认端口）
x tping {{host}}
# Ping 指定主机的特定端口
x tping {{host}}:{{port}}
# 以热力图形式显示结果
x tping {{[-m|--heatmap]}} {{host}}
# 以柱状图形式显示结果
x tping {{[-b|--bar]}} {{host}}:{{port}}

# 打印网络上指定媒体的媒体信息
you-get {{[-i|--info]}} {{https://example.com/video?id=value}}
# 从指定 URL 下载媒体
you-get {{https://example.com/video?id=value}}
# 在 Google 视频上搜索并下载
you-get {{关键词}}
# 将媒体下载到指定位置
you-get {{[-o|--output-dir]}} {{路径/到/目录}} {{[-O|--output-filename]}} {{文件名}} {{https://example.com/watch?v=value}}

# 通过歌曲名称下载（交互式选择）
ytmdl {{歌曲名称}}
# 不提示直接下载第一个结果
ytmdl {{[-q|--quiet]}} {{歌曲名称}}
# 将歌曲下载到指定目录
ytmdl {{[-o|--output-dir]}} {{路径/到/目录}} {{歌曲名称}}
# 从 YouTube URL 下载歌曲
ytmdl --url https://www.youtube.com/watch?v={{oHg5SJYRHA0}}

# 生成一个新的 ZeroTier 身份，并将私钥部分输出到 `stdout`
zerotier-idtool generate
# 生成一个新的 ZeroTier 身份，并将私钥和公钥部分保存到文件中
zerotier-idtool generate {{路径/到/identity.secret}} {{路径/到/identity.public}}
# 生成一个具有指定十六进制靓号前缀的 ZeroTier 身份（可能需要很长时间）
zerotier-idtool generate {{路径/到/identity.secret}} {{路径/到/identity.public}} {{靓号_前缀}}
# 从私钥身份中提取公钥部分
zerotier-idtool getpublic {{路径/到/identity.secret}}

dev.example:
# 显示将执行的变动但不执行（dry-run）
2to3 {{路径/到/文件.py}}
# 将 Python 2 文件转化为 Python 3
2to3 {{[-w|--write]}} {{路径/到/文件.py}}
# 将 Python 2 语言特性转化为 Python 3
2to3 {{[-w|--write]}} {{路径/到/文件.py}} {{[-f|--fix]}} {{raw_input}} {{[-f|--fix]}} {{print}}
# 除了某个语言特性外将所有其他的 Python 2 语言特性转化为 Python 3
2to3 {{[-w|--write]}} {{路径/到/文件.py}} {{[-x|--nofix]}} {{has_key}} {{[-x|--nofix]}} {{isinstance}}

# 与一个安卓设备配对（可在开发者选项中，找到地址和配对码）
adb pair {{ip_地址}}:{{端口}}
# 与一个安卓设备连接（端口与配对时存在差异）
adb connect {{ip_地址}}:{{端口}}
# 断开与设备的连接
adb disconnect {{ip_地址}}:{{端口}}

# 卸载一个软件包
adb uninstall {{com.example.app}}
# 卸载软件包，但是保留用户数据
adb uninstall -k {{com.example.app}}

# 列出已安装的角色或集合
ansible-galaxy {{role|collection}} list
# 使用不同的详细等级搜索角色（`-v` 应该放在最后）
ansible-galaxy role search {{关键字}} -v{{vvvvv}}
# 安装或移除角色
ansible-galaxy role {{install|remove}} {{角色名称1 角色名称2 ...}}
# 创建一个新角色
ansible-galaxy role init {{角色名称}}

# 对指定的 playbook 和角色目录执行 lint 检查
ansible-lint {{路径/到/playbook_文件}} {{路径/到/角色_目录}}
# 在排除特定规则的情况下对 playbook 执行 lint 检查
ansible-lint {{[-x|--exclude-rules]}} {{规则1,规则2,...}} {{路径/到/playbook_文件}}
# 以离线模式对 playbook 执行 lint 检查，并将输出格式化为 PEP8 风格
ansible-lint {{[-o|--offline]}} {{[-p|--parseable]}} {{路径/到/playbook_文件}}
# 使用自定义规则目录对 playbook 执行 lint 检查
ansible-lint {{[-r|--rules]}} {{路径/到/自定义_规则_目录}} {{路径/到/playbook_文件}}

# 通过交互式密码提示创建新的加密保险库文件
ansible-vault create {{路径/到/保险库_文件}}
# 通过交互式密码提示编辑、查看或重新生成密钥（重新加密）现有的加密保险库文件
ansible-vault {{edit|view|rekey}} {{路径/到/保险库_文件}}
# 使用密码文件创建新的加密保险库文件
ansible-vault create --vault-password-file {{路径/到/密码_文件}} {{路径/到/保险库_文件}}
# 使用密码文件原地加密现有的明文文件
ansible-vault encrypt --vault-password-file {{路径/到/密码_文件}} {{路径/到/文件}}

# 构建一个草稿
arduino --verify {{路径/到/文件.ino}}
# 构建草稿，并上传至设备
arduino --upload {{路径/到/文件.ino}}
# 构建草稿，并上传至带有一个 Atmega328p CPU 的 Arduino Nano（连接到端口 `/dev/ttyACM0`）
arduino --board {{arduino:avr:nano:cpu=atmega328p}} --port {{/dev/ttyACM0}} --upload {{路径/到/文件.ino}}
# 将首选项 `名称` 设定为特定 `值`
arduino --pref {{名称}}={{值}}

# 打包一个文件或目录
asar {{[p|pack]}} {{文件或目录路径}} {{输出的 asar 文件}}
# 解压一个 asar 文件
asar {{[e|extract]}} {{asar 文件}}
# 从 asar 文件中解压指定的文件
asar {{[ef|extract-file]}} {{asar 文件}} {{文件}}
# 列出一个 asar 文件中的内容
asar {{[l|list]}} {{asar 文件}}

# 将本地安装的 `asciinema` 与 asciinema.org 账号关联
asciinema auth
# 新建录制并保存到本地文件（按 `<Ctrl d>` 或输入 `exit` 结束）
asciinema rec {{路径/到/录制文件.cast}}
# 从本地文件回放终端录制
asciinema play {{路径/到/录制文件.cast}}
# 回放托管在 <https://asciinema.org> 的终端录制
asciinema play https://asciinema.org/a/{{文件id}}

# 移除指定文件中未使用的变量，并展示 diff
autoflake --remove-unused-variables {{路径/到/文件.py}}
# 移除多个文件中未使用的引入，并展示 diffs
autoflake --remove-all-unused-imports {{路径/到/文件1.py 路径/到/文件2.py ...}}
# 移除未被使用的变量，并覆盖更新
autoflake --remove-unused-variables --in-place {{路径/到/文件.py}}
# 递归地移除指定文件夹下层所有文件中未使用的变量，并覆盖更新
autoflake --remove-unused-variables --in-place --recursive {{路径/到/目录}}

# 转编译指定文件到标准输出
babel {{路径/到/文件}}
# 转编译指定文件，输入为特定文件
babel {{路径/到/输入文件}} --out-file {{路径/到/输出文件}}
# 监听文件变动触发转编译
babel {{路径/到/输入文件}} --watch
# 转编译整个目录下的 js 文件
babel {{路径/到/输入文件目录}}

# 搜索包（crate）
cargo search {{搜索关键词}}
# 安装二进制包（crate）
cargo install {{包名}}
# 列出已安装的二进制包（crate）
cargo install --list
# 在指定目录（或默认情况下在当前工作目录）中创建一个新的二进制或库 Rust 项目
cargo init --{{bin|lib}} {{路径/到/目录}}

# 将多个文件编译为可执行文件
clang {{源/文件/的路径1.c 源/文件/的路径2.c ...}} {{[-o|--output]}} {{可执行/文件/的路径}}
# 打印所有错误和警告
clang {{源/文件/的路径.c}} -Wall {{[-o|--output]}} {{可执行文件}}
# 打印普通警告和调试信息, 并在不影响调试的情况下优化
clang {{源/文件/的路径.c}} -Wall {{[-g|--debug]}} -Og {{[-o|--output]}} {{可执行/文件/的路径}}
# 包含与源文件不在同一路径下的库
clang {{源/文件/的路径.c}} {{[-o|--output]}} {{可执行/文件/的路径}} -I{{头/文件/的目录}} -L{{库/的目录}} -l{{库的名字}}

# 将一组源文件编译为二进制文件
clang++ {{源/文件/的路径1.cpp 源/文件/的路径2.cpp ...}} {{[-o|--output]}} {{可执行/文件/的路径}}
# 打印所有错误和警告
clang++ {{源/文件/的路径.cpp}} -Wall {{[-o|--output]}} {{可执行文件}}
# 打印普通警告和调试信息, 并在不影响调试的情况下优化
clang++ {{源/文件/的路径.cpp}} -Wall {{[-g|--debug]}} -Og {{[-o|--output]}} {{可执行/文件/的路径}}
# 指定 C++ 语言标准
clang++ {{源/文件/的路径.cpp}} -std={{c++20}} {{[-o|--output]}} {{可执行/文件/的路径}}

# 启动 Visual Studio Code
code
# 打开指定的文件或目录
code {{路径/到/文件或目录1 路径/到/文件或目录2 ...}}
# 比较两个指定的文件
code {{[-d|--diff]}} {{路径/到/文件1}} {{路径/到/文件2}}
# 在新窗口中打开指定的文件或目录
code {{[-n|--new-window]}} {{路径/到/文件或目录1 路径/到/文件或目录2 ...}}

# 运行 JavaScript 或 TypeScript 文件
deno run {{路径/到/文件.ts}}
# 启动 REPL（交互式 shell）
deno
# 运行文件并启用网络访问
deno run --allow-net {{路径/到/文件.ts}}
# 从 URL 运行文件
deno run {{https://deno.land/std/examples/welcome.ts}}

# 使用自动重载运行 FastAPI 应用（用于开发）
fastapi run {{路径/文件.py}} --reload
# 在开发模式下运行应用
fastapi dev {{路径/文件.py}}
# 指定运行的主机和端口
fastapi run {{路径/文件.py}} --host {{主机地址}} --port {{端口}}
# 设置应用变量名（如果不是 `app`）或指定自定义应用目录
fastapi run {{路径/文件.py}} --app-dir {{路径/到/应用}} --app {{自定义_app_名称}}

# 将一组源文件编译为二进制文件
g++ {{源/文件/的路径1.cpp 源/文件/的路径2.cpp ...}} {{[-o|--output]}} {{可执行/文件/的路径}}
# 打印所有错误和警告
g++ {{源/文件/的路径.cpp}} -Wall {{[-o|--output]}} {{output_executable}}
# 打印普通警告和调试信息, 并在不影响调试的情况下优化
g++ {{源/文件/的路径.cpp}} -Wall {{[-g|--debug]}} -Og {{[-o|--output]}} {{可执行/文件/的路径}}
# 指定 C++ 语言标准 (C++98/C++11/C++14/C++17)
g++ {{源/文件/的路径.cpp}} -std={{c++98|c++11|c++14|c++17}} {{[-o|--output]}} {{可执行/文件/的路径}}

# 将一组源文件编译为二进制文件
gcc {{源/文件/的路径1.cpp 源/文件/的路径2.cpp ...}} {{[-o|--output]}} {{可执行/文件/的路径}}
# 打印所有错误和警告
gcc {{源/文件/的路径.cpp}} -Wall {{[-o|--output]}} {{output_executable}}
# 打印普通警告和调试信息, 并在不影响调试的情况下优化
gcc {{源/文件/的路径.cpp}} -Wall {{[-g|--debug]}} -Og {{[-o|--output]}} {{可执行/文件/的路径}}
# 包含与源文件不在同一路径下的库
